#include <Adafruit_BMP280.h>

Adafruit_BMP280 bmp;

void setup() {
  Serial.begin(115200);
  if (!bmp.begin(0x76)) {
    Serial.println("BMP280 not found at 0x76 - check SDA/SCL");
    while (true) delay(10);
  }
}

void loop() {
  Serial.print("Temperature: ");
  Serial.print(bmp.readTemperature());
  Serial.print(" C, pressure: ");
  Serial.print(bmp.readPressure() / 100.0);
  Serial.println(" hPa");
  delay(1000);
}
